css:
 div.pagebreak {
     page-break-before: always;
 }

 .body {
     width: 604px;
     min-height: 794px;
     overflow: hidden;
 }

 .headerborder {
     width: 99%;
     display: table;
     border-collapse: collapse;
     border: 2px solid #000000;
 }

 .headerborder + .headerborder {
     border-top: 0px;
 }

 .headercolumn1 {
     width: 25%;
     float: left;
     padding-left: 2px;
 }

 .headercolumn2 {
     width: 2%;
     float: left;
 }

 .headercolumn3 {
     width: 72%;
     float: right;
     padding-right: 2px;
 }

 .printdaterow {
     float: right;
     text-align: right;
     padding-right: 10px;
 }

 .row {
     width: 100%;
     float: left;

     /*Override bootstrap css that breaks TNT format*/
     margin-right: 0px !important;
     margin-left: 0px !important;
}

 .centered {
     text-align: center;
 }

 .Line80 {
     line-height: 80%;
     padding-top: 2px;
 }

 .Line6 {
     height: 6px;
 }

 .Line20 {
     line-height: 40%;
     padding: 2px;
 }

 .Line80fixed13 {
     height: 13px;
     line-height: 80%;
 }

 .Line80fixed15 {
     height: 15px;
     line-height: 80%;
 }

 .Line160 {
     line-height: 160%;
     padding-top: 2px;
 }

 .Line100 {
     line-height: 100%;
     padding-top: 2px;
 }

 .detail {
     min-height: 94px;
 }

 .barcode {
     width: 41%;
     float: left;
 }

 .specinstructions {
     width: 29%;
     float: left;
 }

 .dgsection {
     width: 29%;
     float: left;
 }

 .servicescolumn1 {
     width: 10%;
     float: left;
 }

 .servicescolumn2 {
     width: 90%;
     float: left;
 }

 .totalscolumn1 {
     width: 17%;
     float: left;
 }

 .totalscolumn2 {
     width: 21%;
     float: left;
 }

 .totalscolumn3 {
     width: 29%;
     float: left;
 }

 .totalscolumn4 {
     width: 33%;
     float: left;
 }

 .addresscolumn1 {
     width: 17%;
     float: left;
 }

 .addresscolumn2 {
     width: 83%;
     float: left;
 }

 .contactcolumn1 {
     width: 17%;
     float: left;
 }

 .contactcolumn2 {
     width: 40%;
     float: left;
 }

 .contactcolumn3 {
     width: 42%;
     float: left;
 }

 .rowpart {
     float: left;
 }

 .packages {
     min-height: 57px;
 }

 .packagescolumn1 {
     width: 39%;
     overflow: hidden;
     float: left;
 }

 .packagescolumn2 {
     width: 25%;
     float: left;
 }

 .packagescolumn3 {
     width: 36%;
     float: left;
 }

 .hr {
     width: 100%;
     height: 3px;
     border-bottom: 3px solid #C0C0C0;
     margin-bottom: 2px;
 }

 .separator {
     width: 100%;
     height: 20px;
     float: left;
 }

 .signcolumn1 {
     width: 62%;
     float: left;
 }

 .signcolumn2 {
     width: 37%;
     float: left;
 }

 .UK {
     border-spacing: 3px;
 }

 .padded3 {
     padding: 3px;
 }

 .title {
     width: 370px;
     margin: 0 auto;
     overflow: hidden;
 }


 .UKheaderrow1column1 {
     width: 44%;
     float: left;
 }

 .UKheaderrow1column2 {
     width: 51%;
     float: left;
     text-align: right;
 }

 .UKheaderrow2column1 {
     width: 37%;
     float: left;
 }

 .UKheadercolumn3 {
     width: 20%;
     float: left;
 }

 .padded5 {
     padding: 5px;
 }

 .rowbordered {
     float: left;
     border-spacing: 0px;
     padding: 0px;
     width: 99%;
     border: 2px solid #656566;
 }

 .rowbordered + .rowbordered {
     border-top: 0px solid #656566;
 }

 .internalrowbordered {
     border-spacing: 0px;
     padding: 0px;
     border-bottom: 2px solid #656566;
     overflow: hidden;
 }

 .internalrowbordered:last-child {
     border-bottom: 0px;
 }

 .columnbordered {
     border-spacing: 0px;
     padding: 0px;
     border-right: 2px solid #656566;
 }

 .columnbordered:last-child {
     border-right: 0px;
 }

 .UKcolumn1 {
     float: left;
     width: 325px;
 }

 .UKcolumn2 {
     float: left;
     width: 126px;
 }

 .UKcolumn3 {
     float: left;
     width: 84px;
 }

 .UKcolumn2a {
     float: left;
