 }

 .UKcolumn1b {
     float: left;
     width: 428px;
 }

 .UKcolumn2b {
     float: left;
     width: 167px;
 }

 .UKcolumn3b {
     float: left;
     width: 542px;
 }

 .UKcolumn4 {
     float: left;
     width: 53px;
 }

 .UKbarcodeheight {
     min-height: 93px;
 }

 .UKcontactheight {
     min-height: 40px;
 }

 .UKcontactcolumn1 {
     width: 39%;
     float: left;
 }

 .UKcontactcolumn2 {
     width: 59%;
     float: left;
 }

 .UKrowheight {
     height: 20px;
 }

 .UKserviceheight {
     min-height: 206px;
 }

 img {
     display: inline-block;
     margin: auto;
 }

 img.center {
     margin-top: 9px;
 }

 img.barcodecenter {
     margin-top: 8px;
 }          

 font {
     color: black;
 }

 .bold {
     font-weight: bold;
 }

 font.newtitle {
     font-weight: bold;
     font-family: arial, helvetica, "sans-serif";
     font-size: 9pt;
     text-decoration: underline;
 }

 font.newdata {
     font-family: arial, helvetica, "sans-serif";
     font-size: 8pt;
 }

 font.newheader {
     font-weight: bold;
     font-family: arial, helvetica, "sans-serif";
     font-size: 8pt;
 }

 font.carrierTerms {
     font-family: arial, helvetica "sans-serif";
     font-size: 5pt;
 }

 font.newbarcode {
     font-weight: bold;
     font-family: arial, "sans-serif";
     font-size: 8pt;
     letter-spacing: 0.1cm;
 }
